    ('1795c214-061f-5630-ace2-7e8b8057bf80'::uuid, 'e0a19e09-b987-5025-bd20-6c4f00eeb94e'::uuid, 'Qu’est-ce qu’une source primaire de lumière ?', 'mcq', '["Un objet qui produit sa propre lumière","Un objet qui renvoie la lumière reçue","Un objet transparent","Un objet noir"]'::jsonb, 0, 'Le Soleil et une LED en sont ; la Lune n’en est pas une.', 1),
    ('a8bcc5be-6d8a-5f35-865d-1487564c6aa0'::uuid, 'e0a19e09-b987-5025-bd20-6c4f00eeb94e'::uuid, 'Comment se propage la lumière dans un milieu homogène et transparent ?', 'mcq', '["En ligne droite","En zigzag","En cercle","Elle ne se propage pas"]'::jsonb, 0, 'C’est ce qui explique les ombres et les éclipses.', 2),
    ('22174c3e-5c97-538b-8f5e-5103941f3d8b'::uuid, 'e0a19e09-b987-5025-bd20-6c4f00eeb94e'::uuid, 'Que fait un prisme à la lumière blanche ?', 'mcq', '["Il la disperse en un spectre continu de couleurs","Il l’absorbe entièrement","Il la transforme en son","Il l’accélère"]'::jsonb, 0, 'C’est le même phénomène que dans un arc-en-ciel.', 3),
