    ('c0471ce4-705f-51fd-abc5-2fda7dc1caf5'::uuid, '1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'Le son peut-il se propager dans le vide ?', 'mcq', '["Non, il a besoin d’un milieu matériel","Oui, comme la lumière","Oui, mais plus lentement","Seulement s’il est très fort"]'::jsonb, 0, 'L’expérience de la cloche à vide le démontre.', 2),
    ('c44e8f01-4686-51b4-8672-127c173c8b08'::uuid, '1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'Quelle est la vitesse du son dans l’air ?', 'mcq', '["Environ 340 m/s","Environ 300 000 km/s","Environ 1 500 m/s","Environ 34 m/s"]'::jsonb, 0, '1 500 m/s est sa vitesse dans l’eau.', 3),
    ('bba80480-0ece-5275-9a76-78fbe6fc5e75'::uuid, '1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'Que mesure la fréquence d’un son ?', 'mcq', '["Sa hauteur : grave ou aigu","Son volume","Sa vitesse de propagation","Sa durée"]'::jsonb, 0, 'Elle s’exprime en hertz (Hz).', 4),
    ('4be6b41a-5876-589b-b838-259473ea63bb'::uuid, '1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'Quel est le domaine des fréquences audibles par l’oreille humaine ?', 'mcq', '["Environ 20 Hz à 20 000 Hz","0 Hz à 100 Hz","100 Hz à 1 000 Hz","20 000 Hz à 50 000 Hz"]'::jsonb, 0, 'En dessous ce sont des infrasons, au-dessus des ultrasons.', 5),
    ('202f1974-bac1-5dcf-93a4-25f4b11547b4'::uuid, '1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'Dans quelle unité mesure-t-on le niveau sonore ?', 'mcq', '["Le décibel (dB)","Le hertz (Hz)","Le watt (W)","Le mètre par seconde (m/s)"]'::jsonb, 0, 'Le hertz mesure la fréquence, pas le volume.', 6),
    ('8e6ccb29-02d8-5621-96a8-3a9a45953d14'::uuid, '1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'À partir de quel niveau sonore une exposition prolongée devient-elle dangereuse ?', 'mcq', '["85 dB","30 dB","120 dB seulement","200 dB"]'::jsonb, 0, '120 dB est le seuil de douleur, mais le danger commence bien avant.', 7),
