    ('b44a2bea-c3fb-56a4-b8b0-e557bcdc5a78'::uuid, '0a5510c5-38df-57c7-84c2-07feb5862f56'::uuid, 'Que traduit l’amplitude d’un signal sonore ?', 'mcq', '["L’intensité du son : fort ou faible","La hauteur du son : grave ou aigu","La vitesse du son","La durée du son"]'::jsonb, 0, 'La fréquence, elle, donne la hauteur.', 5),
    ('5f3358ff-c1d3-5091-9d9c-9a6974220d71'::uuid, '0a5510c5-38df-57c7-84c2-07feb5862f56'::uuid, 'Comment appelle-t-on les sons de fréquence supérieure à 20 000 Hz ?', 'mcq', '["Les ultrasons","Les infrasons","Les sons purs","Les harmoniques"]'::jsonb, 0, 'Chauves-souris, sonars et échographies les utilisent.', 6),
    ('eb8f40a0-6fad-5aca-abbb-05c4a4ac74c5'::uuid, '0a5510c5-38df-57c7-84c2-07feb5862f56'::uuid, 'Quelle courbe correspond à un bruit ?', 'mcq', '["Une courbe sans période identifiable","Une sinusoïde parfaite","Une courbe périodique complexe","Une droite"]'::jsonb, 0, 'C’est ce qui le distingue d’une note de musique.', 7),
    ('4db40276-f73c-5d86-8b1e-9dbd6cf257a8'::uuid, '0a5510c5-38df-57c7-84c2-07feb5862f56'::uuid, 'Augmenter l’amplitude d’un son le rend plus aigu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cela le rend plus fort : la hauteur ne dépend que de la fréquence.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('physique-chimie');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('physique-chimie')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 295 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 295 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
